import {MATERIAL_BY_ID} from './material-library.mjs?v=cad18';
import {MECHANISMS,cleanDetails} from './details.mjs?v=cad18';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
export function installAdvanced({scene,current,commit,renderInspector,showPanel,inspectorTab,toast,mode,duplicate,remove,rotate}){let partId=null,moduleId=null,contextPart=null,partTimer;const defaults={x:0,y:0,z:0,rotation:0,finish:'inherit',color:'#ffffff',roughness:.5,textureScale:1,grain:0,textureOffsetX:0,textureOffsetY:0,edgeThickness:1,mechanism:'inherit',style:'inherit',handle:'inherit',handleLength:160,visible:true};
function parts(){return scene.parts();}
function render(){const m=current();if(m?.id!==moduleId){moduleId=m?.id;partId=null;scene.partId=null;}$$('[data-advanced]').forEach(el=>{if(!m)return;const k=el.dataset.advanced;if(el.type==='checkbox')el.checked=m[k];else el.value=m[k];el.disabled=m.locked;});const list=parts();const select=$('#part-select');const old=select.value;select.replaceChildren();const option=document.createElement('option');option.value='';option.textContent='Выберите элемент…';select.add(option);for(const p of list){const o=document.createElement('option');o.value=p.id;o.textContent=p.label;select.add(o);}if(!list.some(p=>p.id===partId))partId=null;select.value=partId||'';$('#part-settings').hidden=!partId;const p=list.find(p=>p.id===partId);$('#part-title').textContent=p?.label||'Выберите деталь';$('#part-path').textContent=m?(m.name+' / '+(p?.label||`${list.length} элементов`)):'';if(!p||!m)return;const o=m.details?.[partId]||{};$$('[data-part]').forEach(el=>{const k=el.dataset.part;let v=o[k]??MATERIAL_BY_ID[o.material]?.[k]??defaults[k]??(k==='open'?m.open:Math.round(p.baseSize?.[k]||0));if(el.type==='checkbox')el.checked=v;else el.value=v;el.disabled=m.locked;});$('#part-open-value').textContent=(o.open??m.open)+'%';$('#part-door-settings').hidden=!['door','drawer','appliance'].includes(p.kind);$('#part-handle-settings').hidden=p.kind!=='handle'||m.type==='cad-reference';$('#part-edge-settings').hidden=!['door','drawer','panel','shelf'].includes(p.kind);$('[data-part=mechanism]').closest('label').hidden=p.kind!=='door';$('[data-part=style]').closest('label').hidden=!['door','drawer'].includes(p.kind);}
function selectPart(id){const m=current();if(!m)return;moduleId=m.id;partId=id;scene.detailMode=true;$('#module-level').setAttribute('aria-pressed','false');$('#part-level').setAttribute('aria-pressed','true');scene.setPart(id);inspectorTab('parts');renderInspector();showPanel('inspector');}
$('#part-select').onchange=e=>selectPart(e.target.value);$('#edit-parts').onclick=()=>selectPart(parts().find(p=>p.kind==='door'||p.kind==='drawer')?.id||parts()[0]?.id);
$('#module-level').onclick=()=>{scene.detailMode=false;$('#module-level').setAttribute('aria-pressed','true');$('#part-level').setAttribute('aria-pressed','false');partId=null;scene.setPart(null);inspectorTab('module');};$('#part-level').onclick=()=>{scene.detailMode=true;$('#module-level').setAttribute('aria-pressed','false');$('#part-level').setAttribute('aria-pressed','true');inspectorTab('parts');toast('Щёлкните деталь в сцене. Двойной щелчок работает в любом режиме.');};
function changePart(el){const m=current();if(!m||!partId||m.locked)return;const k=el.dataset.part;if(el.type==='number'&&(el.value===''||!el.validity.valid))return;let v=el.type==='checkbox'?el.checked:['number','range'].includes(el.type)?Number(el.value):el.value;m.details||={};m.details[partId]||={};m.details[partId][k]=v;if(k==='finish')delete m.details[partId].material;m.details=cleanDetails(m.details);scene.updateModule(m);scene.setPart(partId);$('#part-open-value').textContent=(m.details[partId]?.open??m.open)+'%';clearTimeout(partTimer);partTimer=setTimeout(()=>commit({inspector:false}),250);}
$$('[data-part]').forEach(el=>{el.addEventListener('input',()=>changePart(el));el.addEventListener('change',()=>{changePart(el);clearTimeout(partTimer);commit();});});
$('#reset-part').onclick=()=>{const m=current();if(!m||!partId||m.locked)return;delete m.details[partId];scene.updateModule(m);commit();toast('Настройки детали сброшены');};
$$('[data-advanced]').forEach(el=>{const apply=()=>{const m=current();if(!m||m.locked)return;if(el.type==='number'&&(el.value===''||!el.validity.valid))return;const k=el.dataset.advanced;m[k]=el.type==='checkbox'?el.checked:['number','range'].includes(el.type)||k==='grain'?Number(el.value):el.value;scene.updateModule(m);clearTimeout(partTimer);partTimer=setTimeout(()=>commit({inspector:false}),250);};el.addEventListener('input',apply);el.addEventListener('change',()=>{apply();clearTimeout(partTimer);commit();});});
$('#resize-tool').onclick=()=>{mode('resize');toast('Тяните цветные точки: ширина, высота и глубина.');};
function context(x,y,id){contextPart=id;const m=current(),p=parts().find(p=>p.id===id);$('#context-title').textContent=p?`${m.name} · ${p.label}`:m?.name||'Модуль';const menu=$('#context-menu');menu.querySelector('[data-context=move]').firstChild.textContent=scene.detailMode?'Переместить деталь ':'Переместить модуль ';menu.hidden=false;menu.style.left=Math.max(8,Math.min(innerWidth-252,x))+'px';menu.style.top=Math.max(8,Math.min(innerHeight-menu.offsetHeight-8,y))+'px';menu.querySelector('button').focus({preventScroll:true});}
$('#context-menu').onclick=e=>{const action=e.target.closest('[data-context]')?.dataset.context;if(!action)return;$('#context-menu').hidden=true;const m=current();if(!m)return;if(action==='part'){selectPart(contextPart);return;}if(action==='duplicate'){duplicate();return;}if(action==='lock'){m.locked=!m.locked;commit();return;}if(m.locked){toast('Сначала разблокируйте модуль');return;}if(action==='move'||action==='resize'){if(scene.detailMode&&contextPart)selectPart(contextPart);mode(action);return;}if(action==='rotate'){if(scene.detailMode&&contextPart){m.details||={};m.details[contextPart]||={};m.details[contextPart].rotation=((m.details[contextPart].rotation||0)+90)%360;scene.updateModule(m);commit();}else rotate();return;}if(action==='delete'){remove();return;}if(action==='open'){const p=parts().find(p=>p.id===contextPart);if(p&&['door','drawer','appliance'].includes(p.kind)){m.details||={};m.details[p.id]||={};m.details[p.id].open=(m.details[p.id].open??m.open)>0?0:100;}else m.open=m.open>0?0:100;}if(action==='light')m.light=!m.light;if(action==='power')m.applianceOn=!m.applianceOn;if(action==='hide')m.visible=false;scene.updateModule(m);commit();};
document.addEventListener('pointerdown',e=>{if(!e.target.closest('#context-menu'))$('#context-menu').hidden=true;});document.addEventListener('keydown',e=>{if(e.key==='Escape')$('#context-menu').hidden=true;});
function surface(key){inspectorTab('room');showPanel('inspector');const map={floor:'floor',back:'wall',left:'leftWall',backsplash:'backsplash'};const el=$(`[data-room="${map[key]||'wall'}"]`);el?.focus({preventScroll:true});el?.scrollIntoView({block:'center',behavior:'smooth'});toast(({floor:'Выбран пол',back:'Выбрана задняя стена',left:'Выбрана левая стена',backsplash:'Выбран фартук'}[key])||'Настройки комнаты');}
return {render,selectPart,context,surface,selectedPart:()=>partId};}
